# Reconstruct the demo to verify that left moves retract the tail and collect on contact.
demo=g['demonstrations'][0]
bs=[demo['start']]
for st in demo['steps']:
    bb=[r[:] for r in bs[-1]]
    for x,y,v in st['changes']: bb[y][x]=v
    bs.append(bb)
for i,bb in enumerate(bs):
    objs={}
    for c in [8,9,14]:
        pts=[(x,y) for y in range(12,42) for x in range(64) if bb[y][x]==c]
        if pts: objs[c]=(min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts))
    print(i,objs)
print('planned route: collect e and 9 horizontally, move up, retract left into 8, then right')

g=load(); b=g['board']
for y in list(range(18,42))+list(range(53,62)):
    # compact runs of non-bg / relevant colors
    runs=[]; last=None
    for x,v in enumerate(b[y]+[-1]):
        if v!=last:
            if last is not None and ((y<42 and last not in [4,5]) or (y>=53 and last!=4)): runs.append((start,x-1,last))
            start=x; last=v
    if runs: print(y,runs)
print('last steps',[(s['actions'],s['won'],s['over']) for s in g['play'][0]['steps']])
